solution.solution.cpp:
int larger(int a, int b)
{
    return a > b ? a : b;
}

unitTests:
TEST("first is larger") { CHECK_EQ(larger(9, 4), 9); }
TEST("second is larger") { CHECK_EQ(larger(4, 9), 9); }
TEST("equal") { CHECK_EQ(larger(7, 7), 7); }
TEST("negatives") { CHECK_EQ(larger(-3, -8), -3); }

